pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address ownerActor, uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(ownerActor != address(0));
        mintAmount = bound(mintAmount, 1, type(uint128).max);
        burnAmount = bound(burnAmount, 1, mintAmount);

        vm.deal(ownerActor, 1 ether);

        c.mintToken(ownerActor, mintAmount);

        c.mintToken(address(this), mintAmount);

        uint256 totalBefore = c.totalSupply();

        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.totalSupply() == totalBefore - burnAmount);
        } else {
            assertTrue(ok);
        }
    }
}
